    out = [row[:] for row in grid]

    # The small colored pattern is a key for the broad horizontal sections
    # of the 8-shaped figure. Determine key colors by their vertical position:
    # the key's top, middle, and bottom colors label the figure's sections.
    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (0, 8)]
    if not key:
        return out

    # Colors appearing at the key's highest, intermediate, and lowest rows.
    key_top = min(r for r, c, v in key)
    key_bottom = max(r for r, c, v in key)
    key_mid = (key_top + key_bottom) / 2
    top_colors = [v for r, c, v in key if r == key_top]
    mid_colors = [v for r, c, v in key if abs(r-key_mid) < 1]
    bottom_colors = [v for r, c, v in key if r == key_bottom]

    # Use the color pattern's spatial progression to color contiguous bands.
    colors = []
    for vals in (top_colors, mid_colors, bottom_colors):
        if vals:
            colors.append(vals[0])
    if not colors:
        return out

    rows = [r for r in range(h) if 8 in grid[r]]
    bands = []
    for r in rows:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    # The key colors correspond, in order, to the major 8-bands.
    for i, band in enumerate(bands):
        color = colors[min(i, len(colors)-1)]
        for r in band:
            for c in range(w):
                if grid[r][c] == 8:
                    out[r][c] = color
    return out
